query DioneItems($first: Int, $after: String) {
  dioneItems(first: $first, after: $after) {
    nodes {
      id
      reportId
      source
      sourceId
      title
      kind
      date
      detail
      url
      section
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query DioneMediaLibrary($provider: DioneLibraryProvider!, $limit: Int, $cursor: String) {
  dioneMediaLibrary(provider: $provider, limit: $limit, cursor: $cursor) {
    status
    observedAt
    items {
      id
      title
      kind
    }
    cursor
    truncated
  }
}

